package cn.sixnine.filmlog;
final class MeterGeometry {
    static double[] previewCrop(double width,double height,double aspect){if(!Double.isFinite(width)||!Double.isFinite(height)||!Double.isFinite(aspect)||width<=0||height<=0||aspect<=0)throw new IllegalArgumentException("取景尺寸无效");double w=Math.max(width,height*aspect),h=w/aspect;return new double[]{(width-w)/2,(height-h)/2,w,h};}
    static double[] visibleSensorFraction(double width,double height,double contentWidth,double contentHeight,int rotation){if(width<=0||height<=0||contentWidth<width||contentHeight<height)throw new IllegalArgumentException("取景裁切尺寸无效");double x=width/contentWidth,y=height/contentHeight;return rotation==90||rotation==270?new double[]{y,x}:new double[]{x,y};}
    static double[] sensorPoint(double x,double y,int rotation){PhotoMath.bounded(x,0,1,"横坐标");PhotoMath.bounded(y,0,1,"纵坐标");switch(rotation){case 0:return new double[]{x,y};case 90:return new double[]{y,1-x};case 180:return new double[]{1-x,1-y};case 270:return new double[]{1-y,x};default:throw new IllegalArgumentException("旋转角度无效");}}
    static double placedEv(double measured,int zone){PhotoMath.bounded(measured,-20,30,"点测 EV");if(zone<0||zone>10)throw new IllegalArgumentException("区域须为0至10");return measured+5-zone;}
    static double recommendation(double live,double held,int zone,double correction){if(zone< -1||zone>10)throw new IllegalArgumentException("区域须为0至10");PhotoMath.bounded(correction,-6,6,"测光校准");double base=Double.isFinite(held)?held:live;if(!Double.isFinite(base))throw new IllegalArgumentException("等待有效测光读数");return zone<0?base+correction:placedEv(base+correction,zone);}
    static double relativeZone(double reading,double baseline,int selected){if(!Double.isFinite(reading)||!Double.isFinite(baseline))return Double.NaN;if(selected< -1||selected>10)throw new IllegalArgumentException("区域须为0至10");return (selected<0?5:selected)+reading-baseline;}
    static double zoneFraction(double zone){if(!Double.isFinite(zone))throw new IllegalArgumentException("灰阶位置无效");return (Math.max(-.45,Math.min(10.45,zone))+.5)/11;}
    static double[] wheelProjection(double offset,double height){if(!Double.isFinite(offset)||!Double.isFinite(height)||height<=0)throw new IllegalArgumentException("滚轮尺寸无效");double angle=offset/height*2*Math.asin(1/1.5),radius=height*1.5/2,cos=Math.cos(angle),w=1+.003*radius*(1-cos);return new double[]{radius*Math.sin(angle)/w,1/w,cos,angle};}
}
